package com.example.shortener.feature.link.service;
import com.example.shortener.common.exception.NotFoundException; import com.example.shortener.common.util.CodeGenerator; import com.example.shortener.feature.link.dto.LinkForm; import com.example.shortener.feature.link.entity.*; import com.example.shortener.feature.link.repository.*; import com.example.shortener.feature.tag.service.TagService; import com.example.shortener.feature.user.service.UserService; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ShortLinkService { private final ShortLinkRepository links; private final ClickRepository clicks; private final TagService tags; private final UserService users; private final CodeGenerator codes; private final GeoService geo; public ShortLinkService(ShortLinkRepository l,ClickRepository c,TagService t,UserService u,CodeGenerator g,GeoService geo){links=l;clicks=c;tags=t;users=u;codes=g;this.geo=geo;}
 @Transactional public ShortLink create(String username,LinkForm f){var u=users.findByUsername(username);ShortLink l=new ShortLink(unique(),f.getOriginalUrl(),u);l.setTags(tags.resolveAll(f.getTagsRaw()));return links.save(l);} private String unique(){String c;do{c=codes.generate();}while(links.existsByCode(c));return c;}
 public Page<ShortLink> findByUser(String u,Pageable p){return links.findByUserId(users.findByUsername(u).getId(),p);} public Page<ShortLink> search(String u,String q,Pageable p){return links.search(users.findByUsername(u).getId(),q,p);} public ShortLink owned(String u,Long id){var l=links.findById(id).orElseThrow(()->new NotFoundException("Link not found"));if(l.getUser()==null||!l.getUser().getId().equals(users.findByUsername(u).getId()))throw new NotFoundException("Link not found");return l;}
 @Transactional public ShortLink update(String u,Long id,LinkForm f){var l=owned(u,id);l.setOriginalUrl(f.getOriginalUrl());l.setTags(tags.resolveAll(f.getTagsRaw()));return links.save(l);} @Transactional public void delete(String u,Long id){links.delete(owned(u,id));}
 @Transactional public String resolveAndTrack(String code,String ip,String ua){var l=links.findByCode(code).orElseThrow(()->new NotFoundException("Short link not found"));if(!l.isActive())throw new NotFoundException("Link is disabled");var g=geo.lookup(ip);clicks.save(new Click(ip,ua,g.country(),g.city(),l));return l.getOriginalUrl();} public Page<Click> clickPage(Long id,Pageable p){return clicks.findByShortLinkId(id,p);}
}
